INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'band', 'n.', '/bænd/', '乐队;带子;条纹', 'My brother plays the guitar in a local rock band.', '我哥哥在一支本地摇滚乐队里弹吉他。', 'Music', 1, 0, 'senior', 'wordlist', 'required2', 'U5', 'a rock band', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'perform', 'v.', '/pəˈfɔːm/', '表演;演奏;履行;执行', 'The young singers will perform on stage at the music festival.', '这些年轻歌手将在音乐节上登台表演。', 'Music', 2, 0, 'senior', 'wordlist', 'required2', 'U5', 'perform on stage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'performance', 'n.', '/pəˈfɔːməns/', '表演;演出;表现', 'Their live performance moved everyone in the hall.', '他们的现场演出感动了大厅里的每一个人。', 'Music', 3, 0, 'senior', 'wordlist', 'required2', 'U5', 'a live performance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'performer', 'n.', '/pəˈfɔːmə(r)/', '表演者;演奏者;演员', 'A street performer was playing the violin for the crowd.', '一位街头艺人正为人群拉小提琴。', 'Music', 4, 0, 'senior', 'wordlist', 'required2', 'U5', 'a street performer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'composer', 'n.', '/kəmˈpəʊzə(r)/', '作曲家;作曲者', 'Beethoven is one of the greatest composers in history.', '贝多芬是历史上最伟大的作曲家之一。', 'Music', 5, 0, 'senior', 'wordlist', 'required2', 'U5', 'a famous composer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'composition', 'n.', '/ˌkɒmpəˈzɪʃn/', '(音乐、艺术的)作品;成分;构成', 'He wrote his first composition when he was only nine.', '他九岁时就写出了自己的第一部作品。', 'Music', 6, 0, 'senior', 'wordlist', 'required2', 'U5', 'an original composition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'conductor', 'n.', '/kənˈdʌktə(r)/', '(乐队、合唱团的)指挥;(公交车的)售票员', 'The conductor raised his hands and the music began.', '指挥举起双手,音乐随即响起。', 'Music', 7, 0, 'senior', 'wordlist', 'required2', 'U5', 'an orchestra conductor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'classical', 'adj.', '/ˈklæsɪkl/', '古典的;经典的', 'She fell in love with classical music while singing in the choir.', '她在合唱团唱歌时爱上了古典音乐。', 'Music', 8, 0, 'senior', 'wordlist', 'required2', 'U5', 'classical music', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'album', 'n.', '/ˈælbəm/', '音乐专辑;相册;集邮簿', 'The band recorded their new album in a small studio.', '这支乐队在一间小录音棚里录制了他们的新专辑。', 'Music', 9, 0, 'senior', 'wordlist', 'required2', 'U5', 'release an album', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'studio', 'n.', '/ˈstjuːdiəʊ/', '录音棚;演播室;工作室', 'You do not even need a studio to join a virtual choir.', '加入虚拟合唱团你甚至不需要录音棚。', 'Music', 10, 0, 'senior', 'wordlist', 'required2', 'U5', 'a recording studio', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stage', 'n.', '/steɪdʒ/', '舞台;阶段;时期', 'He felt nervous and excited when invited to perform on the stage.', '被邀请登台表演时,他既紧张又兴奋。', 'Music', 11, 0, 'senior', 'wordlist', 'required2', 'U5', 'on stage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'talent', 'n.', '/ˈtælənt/', '天赋;天资;有才能的人', 'Those who think they have no musical talent can still help.', '那些觉得自己没有音乐天赋的人仍然可以帮忙。', 'Music', 12, 0, 'senior', 'wordlist', 'required2', 'U5', 'musical talent', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'original', 'adj./n.', '/əˈrɪdʒənl/', '原创的;最初的;原件;原作', 'His original compositions became popular among many choirs.', '他的原创作品在许多合唱团中流行起来。', 'Music', 13, 0, 'senior', 'wordlist', 'required2', 'U5', 'original compositions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ordinary', 'adj.', '/ˈɔːdnri/', '普通的;平凡的', 'A virtual choir helps connect ordinary people together.', '虚拟合唱团帮助把普通人联结在一起。', 'Music', 14, 0, 'senior', 'wordlist', 'required2', 'U5', 'ordinary people', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'opportunity', 'n.', '/ˌɒpəˈtjuːnəti/', '机会;时机', 'Imagine having the opportunity to sing with hundreds of others.', '想象一下,你有机会和数百人一起歌唱。', 'Music', 15, 0, 'senior', 'wordlist', 'required2', 'U5', 'have the opportunity to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'enable', 'v.', '/ɪˈneɪbl/', '使能够;使可能', 'A virtual choir enables shy people to add their voices to others.', '虚拟合唱团使害羞的人也能加入自己的歌声。', 'Music', 16, 0, 'senior', 'wordlist', 'required2', 'U5', 'enable sb to do', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'prove', 'v.', '/pruːv/', '证明;表明;结果是', 'The virtual choir has proved to be a positive influence on many lives.', '虚拟合唱团已被证明对许多人的生活有积极影响。', 'Music', 17, 0, 'senior', 'wordlist', 'required2', 'U5', 'prove to be', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'phenomenon', 'n.', '/fəˈnɒmɪnən/', '现象', 'Since then, the virtual choir has become a worldwide phenomenon.', '从那以后,虚拟合唱团成了一种全球现象。', 'Music', 18, 0, 'senior', 'wordlist', 'required2', 'U5', 'a worldwide phenomenon', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'various', 'adj.', '/ˈveəriəs/', '各种各样的;不同的', 'The CD contains various styles of music from around the world.', '这张光盘收录了来自世界各地的各种风格的音乐。', 'Music', 19, 0, 'senior', 'wordlist', 'required2', 'U5', 'various styles of music', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'virtual', 'adj.', '/ˈvɜːtʃuəl/', '虚拟的;事实上的', 'In a virtual choir, singers record themselves alone at home.', '在虚拟合唱团里,歌手们独自在家录下自己。', 'Music', 20, 0, 'senior', 'wordlist', 'required2', 'U5', 'a virtual choir', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'award', 'n./v.', '/əˈwɔːd/', '奖;奖品;授予', 'My favourite singer just won a music award.', '我最喜欢的歌手刚刚赢得了一个音乐奖。', 'Music', 21, 0, 'senior', 'wordlist', 'required2', 'U5', 'win an award', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'impact', 'n.', '/ˈɪmpækt/', '影响;作用;冲击力', 'Music has had a great impact on my life.', '音乐对我的生活产生了巨大的影响。', 'Music', 22, 0, 'senior', 'wordlist', 'required2', 'U5', 'have an impact on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'disease', 'n.', '/dɪˈziːz/', '疾病', 'Two years ago I was told I had a serious disease.', '两年前我被告知患上了一种严重的疾病。', 'Music', 23, 0, 'senior', 'wordlist', 'required2', 'U5', 'a serious disease', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cure', 'v./n.', '/kjʊə(r)/', '治愈;治疗;解决;药物;办法', 'She found that making music was a cure for her sadness.', '她发现创作音乐是治愈她悲伤的良方。', 'Music', 24, 0, 'senior', 'wordlist', 'required2', 'U5', 'a cure for', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'treatment', 'n.', '/ˈtriːtmənt/', '治疗;对待;处理', 'During the medical treatment, the doctor had her listen to music.', '在治疗过程中,医生让她听音乐。', 'Music', 25, 0, 'senior', 'wordlist', 'required2', 'U5', 'a medical treatment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'relief', 'n.', '/rɪˈliːf/', '(痛苦的)减轻;宽慰;解脱', 'Music gave me strength and brought me relief.', '音乐给了我力量,也带给我宽慰。', 'Music', 26, 0, 'senior', 'wordlist', 'required2', 'U5', 'bring relief', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'satisfaction', 'n.', '/ˌsætɪsˈfækʃn/', '满足;满意;欣慰', 'Music gave me hope and a sense of satisfaction.', '音乐给了我希望和一种满足感。', 'Music', 27, 0, 'senior', 'wordlist', 'required2', 'U5', 'a sense of satisfaction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'soul', 'n.', '/səʊl/', '灵魂;心灵', 'Sad love songs often touch the souls of those who listen.', '悲伤的情歌常常打动听者的心灵。', 'Music', 28, 0, 'senior', 'wordlist', 'required2', 'U5', 'touch the soul', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'energy', 'n.', '/ˈenədʒi/', '精力;能量;能源', 'I like to listen to dance music because it gives me energy.', '我喜欢听舞曲,因为它给我能量。', 'Music', 29, 0, 'senior', 'wordlist', 'required2', 'U5', 'give energy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'previous', 'adj.', '/ˈpriːviəs/', '先前的;以往的', 'Through music he felt the beauty he had known in his previous days.', '透过音乐,他感受到了往日所熟悉的美。', 'Music', 30, 0, 'senior', 'wordlist', 'required2', 'U5', 'his previous life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'gradual', 'adj.', '/ˈɡrædʒuəl/', '逐渐的;渐进的', 'Even affected by gradual blindness, Henry kept writing music.', '即使受逐渐失明的影响,亨利仍坚持作曲。', 'Music', 31, 0, 'senior', 'wordlist', 'required2', 'U5', 'gradual progress', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'capable', 'adj.', '/ˈkeɪpəbl/', '有能力的;有才能的', 'He was still capable of writing beautiful compositions.', '他仍然能够创作出优美的作品。', 'Music', 32, 0, 'senior', 'wordlist', 'required2', 'U5', 'be capable of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'unemployed', 'adj.', '/ˌʌnɪmˈplɔɪd/', '失业的;待业的', 'Once unemployed, the singer finally got the chance to record a song.', '曾经失业的这位歌手终于有了录歌的机会。', 'Music', 33, 0, 'senior', 'wordlist', 'required2', 'U5', 'be unemployed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'equipment', 'n.', '/ɪˈkwɪpmənt/', '设备;装备', 'Some volunteers will set up the equipment before the show.', '一些志愿者会在演出前架设好设备。', 'Music', 34, 0, 'senior', 'wordlist', 'required2', 'U5', 'set up equipment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'aim', 'n./v.', '/eɪm/', '目的;目标;旨在;力求', 'The aim of this festival is to bring people together through music.', '这个音乐节的目的是通过音乐把人们聚到一起。', 'Music', 35, 0, 'senior', 'wordlist', 'required2', 'U5', 'the aim of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'addition', 'n.', '/əˈdɪʃn/', '增加;添加;加法', 'In addition to singing, you could help sell festival tickets.', '除了唱歌,你还可以帮忙卖音乐节门票。', 'Music', 36, 0, 'senior', 'wordlist', 'required2', 'U5', 'in addition to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'moreover', 'adv.', '/mɔːrˈəʊvə(r)/', '而且;此外', 'Moreover, music gave me hope during those hard times.', '此外,在那些艰难的日子里音乐给了我希望。', 'Music', 37, 0, 'senior', 'wordlist', 'required2', 'U5', 'moreover', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'thus', 'adv.', '/ðʌs/', '因此;如此;这样', 'People sing with one voice and thus make the world better.', '人们用同一个声音歌唱,从而让世界变得更美好。', 'Music', 38, 0, 'senior', 'wordlist', 'required2', 'U5', 'thus', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'somehow', 'adv.', '/ˈsʌmhaʊ/', '以某种方式;不知怎么地', 'I hope you will somehow begin to treasure music in your life.', '我希望你能以某种方式开始珍视生活中的音乐。', 'Music', 39, 0, 'senior', 'wordlist', 'required2', 'U5', 'somehow', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'nowadays', 'adv.', '/ˈnaʊədeɪz/', '现在;如今', 'Nowadays millions of performances are uploaded online every day.', '如今每天都有数百万场演出被上传到网上。', 'Music', 40, 0, 'senior', 'wordlist', 'required2', 'U5', 'nowadays', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'altogether', 'adv.', '/ˌɔːltəˈɡeðə(r)/', '总共;完全;全部地', 'Altogether, more than two thousand young people joined the choir.', '总共有两千多名年轻人加入了这个合唱团。', 'Music', 41, 0, 'senior', 'wordlist', 'required2', 'U5', 'altogether', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'assume', 'v.', '/əˈsjuːm/', '假设;以为;认为', 'Can I assume that the aim of the festival is to raise money?', '我可以认为这个音乐节的目的是筹款吗?', 'Music', 42, 0, 'senior', 'wordlist', 'required2', 'U5', 'assume that', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'romantic', 'adj.', '/rəʊˈmæntɪk/', '浪漫的', 'Moved by his romantic words, she accepted his gift.', '被他浪漫的话语打动,她接受了他的礼物。', 'Music', 43, 0, 'senior', 'wordlist', 'required2', 'U5', 'romantic words', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'lean', 'v.', '/liːn/', '依靠;倚靠;倾斜', 'Music was the rock I leant on to get through hard times.', '音乐是我赖以度过艰难时光的依靠。', 'Music', 44, 0, 'senior', 'wordlist', 'required2', 'U5', 'lean on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reaction', 'n.', '/riˈækʃn/', '反应;回应', 'Encouraged by the positive reaction of the audience, she kept playing.', '受到观众积极反应的鼓舞,她坚持演奏下去。', 'Music', 45, 0, 'senior', 'wordlist', 'required2', 'U5', 'a positive reaction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'piano', 'n.', '/piˈænəʊ/', '钢琴', 'My parents wanted me to learn to play the piano at the age of six.', '父母想让我在六岁时学习弹钢琴。', 'Music', 46, 0, 'senior', 'wordlist', 'required2', 'U5', 'play the piano', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'hip-hop', 'n.', '/ˈhɪp hɒp/', '嘻哈音乐;嘻哈文化', 'When I listen to hip-hop, I just have to move.', '我一听嘻哈音乐就忍不住想动起来。', 'Music', 47, 0, 'senior', 'wordlist', 'required2', 'U5', 'hip-hop music', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'stringed', 'adj.', '/strɪŋd/', '有弦的;弦乐的', 'The pipa is a traditional Chinese stringed instrument.', '琵琶是一种传统的中国弦乐器。', 'Music', 48, 0, 'senior', 'wordlist', 'required2', 'U5', 'a stringed instrument', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.01', '①过去分词作时间/原因状语(被动·完成,逻辑主语=主句主语)', 'A2', 10, '必修二 U5 — 当被省略的状语从句主语与主句主语一致、且二者是被动或已完成关系时,把从句压缩成过去分词放句首作时间/原因状语:Moved by his words, she accepted his gift.(= Because she was moved…)', 1, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.02', '②过去分词作条件/让步状语(if / though 引导可与过去分词搭配)', 'A2', 10, '必修二 U5 — 表示条件用 Given more time, we could finish.(= If we were given…);表示让步常保留连词:Though invited, he didn''t come.(= Though he was invited…)。', 2, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u5.03', '③分词逻辑主语 = 主句主语:被动用 done,主动用 doing', 'A2', 10, '必修二 U5 — 分词的逻辑主语必须是主句主语。主语承受动作(被动/完成)→ 过去分词 done;主语发出动作(主动/进行)→ 现在分词 doing。Used for performances, the hall is full of energy.(被动)≠ Using…(主动)。', 3, 'required2', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by his romantic words, the girl finally accepted his gift."', 'Moved', 'Moving', 'To move', 'Move', 'A', '主句主语 the girl 是被打动的对象(被动),作原因状语 → 过去分词 Moved。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ in dark colours, the room needed some bright lights."', 'Painting', 'Painted', 'To paint', 'Paint', 'B', 'the room 是被刷漆的(被动·已完成),作原因状语 → Painted。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by this music, Whitacre said it was like seeing colour for the first time."', 'Inspiring', 'To inspire', 'Inspired', 'Inspire', 'C', '主语 Whitacre 被音乐激励(被动),作原因状语 → Inspired。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ in the USA in 1970, Whitacre began studying music in 1988."', 'Bearing', 'To bear', 'Bear', 'Born', 'D', '出生用 be born,主语被''生于''某地(被动),作时间状语 → Born。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by the audience''s cheers, the young singer played even better."', 'Encouraged', 'Encouraging', 'To encourage', 'Encourage', 'A', '主语 the singer 被掌声鼓舞(被动),作原因状语 → Encouraged。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ in a new way, the album was expected to be popular with fans."', 'Recording', 'Recorded', 'To record', 'Record', 'B', 'the album 是被录制的(被动·完成),作原因状语 → Recorded。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ to perform on the stage, he felt both nervous and excited."', 'Inviting', 'To invite', 'Invited', 'Invite', 'C', '主语 he 是被邀请的(被动),作原因状语 → Invited。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ for many years, the old piano still made a lovely sound."', 'Using', 'To use', 'Use', 'Used', 'D', 'the piano 是被使用的(被动),作时间/原因状语 → Used。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by his teacher from time to time, Henry slowly lost interest in singing."', 'Corrected', 'Correcting', 'To correct', 'Correct', 'A', '主语 Henry 被老师纠正(被动),作原因状语 → Corrected。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ with team spirit, the band members always act as a whole."', 'Filling', 'Filled', 'To fill', 'Fill', 'B', 'the members 充满团队精神(be filled with,被动),作原因状语 → Filled。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ deeply by the song ''Happy'', Sarah began to listen to music every day."', 'Touching', 'To touch', 'Touched', 'Touch', 'C', '主语 Sarah 被歌曲打动(被动),作原因状语 → Touched。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ from university in 1995, Whitacre soon studied at the Juilliard School."', 'Graduating', 'To graduate', 'Graduate', 'Graduated', 'D', '主语与毕业是完成关系,过去分词表完成 → Graduated(此处用作时间状语,= After he graduated)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ in reading her students'' minds, the piano teacher soon noticed my problem."', 'Experienced', 'Experiencing', 'To experience', 'Experience', 'A', 'the teacher 富有经验(be experienced in,被动形式),作原因状语 → Experienced。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ and terrified at the same time, I could only agree to perform."', 'Surprising', 'Surprised', 'To surprise', 'Surprise', 'B', '主语 I 是被惊到的(被动),作原因状语 → Surprised。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by the disease, she thought she did not have much longer to live."', 'Frightening', 'To frighten', 'Frightened', 'Frighten', 'C', '主语 she 被疾病吓到(被动),作原因状语 → Frightened。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ all over the world, the virtual choir has brought people together."', 'Seeing', 'To see', 'See', 'Seen', 'D', 'the choir 被全世界看到(被动),作时间/原因状语 → Seen。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by his fans'' videos, Whitacre joined them into one performance."', 'Inspired', 'Inspiring', 'To inspire', 'Inspire', 'A', '主语 Whitacre 受到启发(被动),作原因状语 → Inspired。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ for a good cause, the music festival drew the whole school together."', 'Holding', 'Held', 'To hold', 'Hold', 'B', 'the festival 是被举办的(被动),作原因状语 → Held。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ onto the Internet, the videos were then joined into one virtual choir."', 'Uploading', 'To upload', 'Uploaded', 'Upload', 'C', '主句主语 the videos 被上传(被动)→ 过去分词 Uploaded;视频不会主动''上传'',故不用 Uploading。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ by the rhythm of hip-hop, the children could not stop dancing."', 'Exciting', 'To excite', 'Excite', 'Excited', 'D', '主语 the children 被节奏点燃(被动),作原因状语 → Excited。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.01'), '"____ in music since childhood, she chose to study composition at university."', 'Interested', 'Interesting', 'To interest', 'Interest', 'A', '主语 she 对音乐感兴趣(be interested in,被动),作原因状语 → Interested。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ more time, the band could have finished recording the whole album."', 'Giving', 'Given', 'To give', 'Give', 'B', '表条件 = If the band had been given…,主语被给予(被动)→ 过去分词 Given。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Though ____ to the contest, the shy boy still refused to sing on stage."', 'inviting', 'to invite', 'invited', 'invite', 'C', '让步从句保留 though,主语被邀请(被动)→ 过去分词 invited(= though he was invited)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ properly, this old guitar could still produce a beautiful tone."', 'Repairing', 'To repair', 'Repair', 'Repaired', 'D', '表条件 = If it were repaired…,吉他被修(被动)→ Repaired。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Even though ____ by gradual blindness, Henry kept writing his music."', 'affected', 'affecting', 'to affect', 'affect', 'A', '让步从句,主语 Henry 被失明影响(被动)→ affected(= though he was affected)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ enough practice, even an ordinary person can play well in public."', 'Giving', 'Given', 'To give', 'Give', 'B', '表条件 = If one is given…,主语被给予(被动)→ Given。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Though ____ in dark colours, the small studio still felt warm and friendly."', 'painting', 'to paint', 'painted', 'paint', 'C', '让步从句,the studio 被刷成深色(被动)→ painted。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ a little more encouragement, the unemployed singer would not have quit."', 'Offering', 'To offer', 'Offer', 'Offered', 'D', '表条件 = If he had been offered…,主语被给予(被动)→ Offered。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Although ____ by the media many times, the band members were never discouraged."', 'questioned', 'questioning', 'to question', 'question', 'A', '让步从句,主语被媒体质疑(被动)→ questioned。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ the right equipment, anyone can set up a small home studio today."', 'Giving', 'Given', 'To give', 'Give', 'B', '表条件 = If one is given…,主语被给予设备(被动)→ Given。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Though ____ for performances, the Silver Hall is open to visitors in the day."', 'using', 'to use', 'used', 'use', 'C', '让步从句,the hall 被用于演出(被动)→ used。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ a fair chance, the street performer could become a real star."', 'Allowing', 'To allow', 'Allow', 'Allowed', 'D', '表条件 = If he were allowed…,主语被给予机会(被动)→ Allowed。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Even if ____ to a famous studio, she would still write her own songs."', 'invited', 'inviting', 'to invite', 'invite', 'A', '条件/让步从句,主语被邀请(被动)→ invited。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ proper training, an ordinary student can learn to read a musical score."', 'Giving', 'Given', 'To give', 'Give', 'B', '表条件 = If a student is given…,主语被给予训练(被动)→ Given。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Though ____ by sadness, Beethoven still completed his greatest works."', 'marking', 'to mark', 'marked', 'mark', 'C', '让步从句,主语的生活被悲伤所笼罩(be marked by,被动)→ marked。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ a louder microphone, the singer could have reached the back rows."', 'Handing', 'To hand', 'Hand', 'Handed', 'D', '表条件 = If he had been handed…,主语被递给(被动)→ Handed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Although ____ many times by judges, the talented girl never lost heart."', 'refused', 'refusing', 'to refuse', 'refuse', 'A', '让步从句,主语被评委拒绝(被动)→ refused。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ enough time on stage, the new band would surely win the audience."', 'Giving', 'Given', 'To give', 'Give', 'B', '表条件 = If the band were given…,主语被给予时间(被动)→ Given。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Though ____ in a poor village, the young composer dreamed of great music."', 'raising', 'to raise', 'raised', 'raise', 'C', '让步从句,主语在村里被养大(be raised,被动)→ raised。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"____ a chance to record, the unemployed man finally shared his song with the world."', 'Offering', 'To offer', 'Offer', 'Offered', 'D', '表条件 = If/Once he was offered…,主语被给予机会(被动)→ Offered。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.02'), '"Even though ____ by his own teachers, the boy never gave up the piano."', 'discouraged', 'discouraging', 'to discourage', 'discourage', 'A', '让步从句,主语被老师们打击(被动)→ discouraged。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ for singing performances, the Silver Hall is always full of energy."', 'Using', 'Used', 'To use', 'Use', 'B', '主句主语 the hall 被用于演出(被动)→ 过去分词 Used;若用 Using 则错(大厅不会主动''使用'')。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ their own videos at home, the choir members later joined them into one."', 'Recorded', 'To record', 'Recording', 'Record', 'C', '主句主语 the members 主动录制(主动)→ 现在分词 Recording;此处主语发出动作,不能用 Recorded。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ in 12 different countries, the singers were joined into one online video."', 'Filming', 'To film', 'Film', 'Filmed', 'D', '主句主语 the singers 被拍摄(被动)→ 过去分词 Filmed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ his fans to send videos, Whitacre created his first virtual choir."', 'Asking', 'Asked', 'To ask', 'Ask', 'A', '主句主语 Whitacre 主动请求(主动)→ 现在分词 Asking;主语发出动作,不能用 Asked。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ by millions online, his first virtual choir became world-famous."', 'Viewing', 'Viewed', 'To view', 'View', 'B', '主句主语 the choir 被观看(被动)→ 过去分词 Viewed。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ Mozart''s classical music, the student felt his whole world light up."', 'Heard', 'To hear', 'Hearing', 'Hear', 'C', '主句主语 the student 主动听(主动)→ 现在分词 Hearing;主语发出动作,不能用 Heard。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ in a quiet studio, the new song sounded warm and clear."', 'Producing', 'To produce', 'Produce', 'Produced', 'D', '主句主语 the song 被制作(被动)→ 过去分词 Produced。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ the violin on the street, the boy soon drew a large crowd."', 'Playing', 'Played', 'To play', 'Play', 'A', '主句主语 the boy 主动拉琴(主动)→ 现在分词 Playing;主语发出动作,不能用 Played。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ with great care, the old album still plays without a single problem."', 'Keeping', 'Kept', 'To keep', 'Keep', 'B', '主句主语 the album 被保管(被动)→ 过去分词 Kept。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ together every weekend, the band slowly built a loyal following."', 'Practised', 'To practise', 'Practising', 'Practise', 'C', '主句主语 the band 主动排练(主动)→ 现在分词 Practising;主语发出动作,不能用 Practised。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ by a famous composer, the song quickly spread around the world."', 'Writing', 'To write', 'Write', 'Written', 'D', '主句主语 the song 被创作(被动)→ 过去分词 Written。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ the audience with her voice, the singer forgot all her nerves."', 'Touching', 'Touched', 'To touch', 'Touch', 'A', '主句主语 the singer 主动打动观众(主动)→ 现在分词 Touching;主语发出动作,不能用 Touched。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ in dark colours, the concert hall needed much brighter lights."', 'Painting', 'Painted', 'To paint', 'Paint', 'B', '主句主语 the hall 被刷漆(被动)→ 过去分词 Painted。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ a happy song to the patients, the doctor helped them relax."', 'Played', 'To play', 'Playing', 'Play', 'C', '主句主语 the doctor 主动放歌(主动)→ 现在分词 Playing;主语发出动作,不能用 Played。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ thousands of times online, the simple folk song became a hit."', 'Sharing', 'To share', 'Share', 'Shared', 'D', '主句主语 the song 被分享(被动)→ 过去分词 Shared。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ her own piano piece, the nervous girl gradually calmed down."', 'Performing', 'Performed', 'To perform', 'Perform', 'A', '主句主语 the girl 主动演奏(主动)→ 现在分词 Performing;主语发出动作,不能用 Performed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ for years in a small band, the guitar still sounds wonderful."', 'Using', 'Used', 'To use', 'Use', 'B', '主句主语 the guitar 被使用(被动)→ 过去分词 Used。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ the crowd to clap along, the street performer smiled brightly."', 'Invited', 'To invite', 'Inviting', 'Invite', 'C', '主句主语 the performer 主动邀请(主动)→ 现在分词 Inviting;主语发出动作,不能用 Invited。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U5' AND code='u5.03'), '"____ in 1827, Beethoven''s music is still loved all over the world."', 'Composing', 'To compose', 'Compose', 'Composed', 'D', '主句主语 the music 被创作(被动)→ 过去分词 Composed。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Virtual Choir', 'Imagine having the opportunity to sing together with hundreds of other people while you are at home alone. You can do this in a virtual choir. Members record themselves while they perform alone on video. These videos are uploaded onto the Internet, and then they are put together into one video that you can watch online. Anyone can take part from anywhere; all you need is a video camera and an Internet connection. You do not even need a studio. A virtual choir helps connect ordinary people. Many of them do not have friends who share their interest in music, and many others do not have the chance to join a local choir. A virtual choir enables them to add their voices to those of other singers and become part of a global community. It has proved to be a positive influence on the lives of many people. As one member said, music helps him forget his problems and become someone else.', '说明·虚拟合唱团', 162, '[{"q":"What is the main thing a person needs to join a virtual choir?","answer":"A","options":["Only a camera and a way to get online.","A professional recording studio.","A famous teacher to help them.","A large group of friends nearby."],"explanation":"原文 ''all you need is a video camera and an Internet connection'' 的转述;明确说不需要 studio。"},{"q":"How are the separate videos turned into a choir?","answer":"B","options":["They are printed out on paper.","They are joined into one video to watch online.","They are sold in local music shops.","They are kept secret from the public."],"explanation":"原文 ''put together into one video that you can watch online'' 的转述。"},{"q":"Why is a virtual choir helpful for ordinary people?","answer":"A","options":["It lets them join in even without local friends or a local choir.","It pays them money to sing.","It teaches them to write music.","It removes all other kinds of music."],"explanation":"中段说许多人没有同好朋友、也无法加入本地合唱团,虚拟合唱团让他们也能参与的转述。"}]'::jsonb, '[{"word":"virtual","cn":"虚拟的"},{"word":"choir","cn":"合唱团"},{"word":"ordinary","cn":"普通的"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'So Many Kinds of Music', 'There are many different kinds of music in the world, and each one makes us feel a different way. Classical music, written long ago by great composers, can sound peaceful, like sitting beside a quiet stream. Hip-hop has a strong beat that makes many young people want to move and dance. Country music often tells simple stories that touch the heart, while rock music feels full of power and energy. Some people enjoy folk songs from their own region, because the tunes remind them of home and the people they love. Others like dance music when they exercise, because it gives them energy. There is no single kind of music that is best for everyone. The same song may make one listener happy and leave another feeling bored. What matters is finding the music that speaks to you. Whatever style you choose, music has a special power to change how you feel and to bring people of different ages and cultures closer together.', '说明·不同音乐类型', 163, '[{"q":"According to the text, how does classical music often make listeners feel?","answer":"B","options":["Angry and tired.","Calm and peaceful.","Frightened and lost.","Bored and sleepy."],"explanation":"原文把古典乐比作坐在安静溪水边,''peaceful'' 的转述。"},{"q":"Why do some people enjoy folk songs from their own region?","answer":"C","options":["Because the songs are very short.","Because folk songs are the loudest.","Because such songs make them think of home and family.","Because no one else can hear them."],"explanation":"原文 ''remind them of home and the people they love'' 的转述。"},{"q":"What main point does the writer make about choosing music?","answer":"D","options":["Only classical music is worth hearing.","Young people should avoid hip-hop.","Everyone must like the same songs.","No single kind suits everyone, so find what speaks to you."],"explanation":"原文 ''no single kind of music that is best for everyone… finding the music that speaks to you'' 的转述。"}]'::jsonb, '[{"word":"classical","cn":"古典的"},{"word":"beat","cn":"节拍"},{"word":"energy","cn":"活力"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Why Learn to Play Music', 'Why should ordinary students spend their time learning to play music? Some people think it is a waste of hours that could be used for exams. Yet learning an instrument brings many quiet rewards. First, it teaches patience. Nobody plays the piano well after a single lesson; real progress is gradual and comes only after months of practice. Second, music gives us a way to express feelings that are hard to put into words. After a long, difficult day, sitting down to play can bring a sense of relief and satisfaction. Third, playing in a band or choir teaches young people to listen to one another and to work as a team, since one wrong note can affect the whole group. Finally, the music we make does not have to be perfect to be valuable. Even a simple tune, played from the heart, can give us hope and remind us that we are capable of creating something beautiful. For all these reasons, learning music is time well spent.', '议论·为何学音乐', 168, '[{"q":"What do some people wrongly believe about learning music, according to the writer?","answer":"A","options":["That it wastes time better spent on exams.","That it is too cheap.","That it makes students unhealthy.","That only teachers can enjoy it."],"explanation":"原文 ''a waste of hours that could be used for exams'' 的转述,作者随后反驳。"},{"q":"Why does the writer say music teaches patience?","answer":"B","options":["Because instruments are very cheap.","Because progress is slow and needs months of practice.","Because music must always be loud.","Because lessons are held at night."],"explanation":"原文 ''real progress is gradual and comes only after months of practice'' 的转述。"},{"q":"What does playing in a band or choir help young people learn?","answer":"C","options":["How to play alone.","How to sell tickets.","How to listen to others and work as a team.","How to write exams faster."],"explanation":"原文 ''teaches young people to listen to one another and to work as a team'' 的转述。"}]'::jsonb, '[{"word":"gradual","cn":"渐进的"},{"word":"relief","cn":"宽慰"},{"word":"capable","cn":"有能力的"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Street Performer', 'Every Saturday morning, an old man set up his violin near the busy market. He was not famous and had never recorded an album, yet people stopped to listen. At first he had been unemployed for a long time, and playing in the street was the only stage he had. His fingers were no longer young, but the music he made was warm and true. Children danced, and tired shoppers smiled and dropped a few coins into his open case. One cold morning a girl asked him why he kept playing when so few people gave him money. The old man answered that he did not play for the coins. He played because music gave his ordinary days meaning, and because a single tune could lift the mood of the whole street. Moved by his words, the girl came back the next week, this time with her own small guitar. Slowly, the two of them turned a quiet corner of the market into a little stage full of energy and joy.', '记叙·街头艺人', 171, '[{"q":"Why was the street the old man''s only stage at first?","answer":"D","options":["Because he disliked indoor halls.","Because he owned the market.","Because he was a famous star.","Because he had been out of work for a long time."],"explanation":"原文 ''had been unemployed for a long time, and playing in the street was the only stage he had'' 的转述。"},{"q":"What reason did the old man give for playing?","answer":"A","options":["Playing gave meaning to his plain days and cheered the whole street.","He needed the coins to live.","He wanted to become famous.","He was forced to play by others."],"explanation":"原文 ''he did not play for the coins… music gave his ordinary days meaning… lift the mood of the whole street'' 的转述。"},{"q":"What did the girl do after hearing his answer?","answer":"B","options":["She told him to stop playing.","She returned the next week with her own guitar.","She gave him a large amount of money.","She never came to the market again."],"explanation":"原文 ''the girl came back the next week… with her own small guitar'' 的转述。"}]'::jsonb, '[{"word":"unemployed","cn":"失业的"},{"word":"stage","cn":"舞台"},{"word":"moved","cn":"被打动的"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Medicine of the Mind', 'Two years ago, Sarah was told she had a serious disease that was difficult to cure. Her body ached all the time, and she felt afraid and alone. One day she had to go through a long medical treatment. To help her relax, the doctor played some music, and one of the songs was simply called ''Happy''. That song made her feel so much better that, from then on, she began to listen to music every day. Music gave her happiness when she had little to smile about. It gave her strength and brought her relief during the hardest hours. It became the rock she leant on to get through that frightening time. Moreover, it gave her hope and a quiet sense of satisfaction, almost like a best friend that spoke words of encouragement. Sarah does not say that music cured her disease by itself. What she does say is that, during the darkest period of her life, music helped her in a way that no medicine alone ever could.', '记叙·音乐的力量', 170, '[{"q":"How did Sarah first come to listen to music every day?","answer":"C","options":["Her teacher ordered her to do so.","She wanted to become a singer.","A song during her treatment made her feel much better.","She read about it in a newspaper."],"explanation":"原文 ''the doctor played some music… made her feel so much better that, from then on, she began to listen to music every day'' 的转述。"},{"q":"What does the writer compare music to during Sarah''s hard time?","answer":"D","options":["A heavy stone in her way.","A short and boring holiday.","A loud and painful noise.","A rock she leant on and a best friend."],"explanation":"原文 ''the rock she leant on… like a best friend'' 的转述。"},{"q":"What is Sarah careful NOT to claim?","answer":"A","options":["That music alone cured her disease.","That she ever felt afraid.","That music gave her hope.","That she listened to a song called ''Happy''."],"explanation":"末段 ''does not say that music cured her disease by itself'' 的转述。"}]'::jsonb, '[{"word":"disease","cn":"疾病"},{"word":"treatment","cn":"治疗"},{"word":"satisfaction","cn":"满足"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Instruments from Around the World', 'Music is made on instruments, and every culture has invented its own. Stringed instruments, such as the violin and the Chinese pipa, make sound when their strings are touched, plucked or rubbed with a bow. Wind instruments, such as the flute and the Scottish bagpipes, sing when air is pushed through them. Then there are the drums and other instruments that are struck to keep the beat. When several of these are played together, we call the group a band or an orchestra, and one person, the conductor, often stands in front to keep everyone together. Learning to play almost any instrument takes patience, because the first sounds a beginner makes are usually far from beautiful. Yet, given enough practice, ordinary hands can be trained to create wonderful music. Around the world, the instruments may look and sound very different, but the wish behind them is the same: people everywhere want to turn simple objects of wood, metal and string into something that can move the human heart.', '说明·乐器与乐队', 168, '[{"q":"How do stringed instruments such as the pipa make sound?","answer":"B","options":["By pushing air through them.","By having their strings touched, plucked or rubbed.","By being struck like drums.","By being left silent."],"explanation":"原文 ''make sound when their strings are touched, plucked or rubbed with a bow'' 的转述。"},{"q":"What is the conductor''s job in a band or orchestra?","answer":"C","options":["To sell the tickets.","To build the instruments.","To stand in front and keep everyone together.","To play the loudest drum."],"explanation":"原文 ''the conductor, often stands in front to keep everyone together'' 的转述。"},{"q":"What does the writer say is the same in every culture?","answer":"D","options":["The exact shape of every instrument.","The price of all instruments.","The number of strings on each instrument.","The wish to turn simple objects into music that moves the heart."],"explanation":"末句 ''the wish behind them is the same… something that can move the human heart'' 的转述。"}]'::jsonb, '[{"word":"stringed","cn":"有弦的"},{"word":"bagpipes","cn":"风笛"},{"word":"conductor","cn":"指挥"}]'::jsonb, 2, 'required2', 'U5');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'Learning the Piano', 'When I was six, my parents wanted me to learn to play the (1)____. To be a good daughter, I agreed, even though I was not very (2)____ in it at all. Experienced in reading her students'' minds, my teacher could soon (3)____ that my heart was not in it. After learning for about six months, I was (4)____ to perform at the year-end concert. Surprised and a little terrified, I could only (5)____. Because I was a beginner, I chose a fairly simple (6)____. To play it well, I (7)____ the same piece for an hour every day. On the day of the concert I was so nervous that I almost wanted to give (8)____. As it turned out, all my hard work paid off and I played (9)____. Encouraged by the warm reaction of the audience, I have continued to play and now (10)____ it more every day.', 150, 2, '[{"q":"1","answer":"A","options":["piano","market","ticket","window"],"explanation":"play the piano 弹钢琴。"},{"q":"2","answer":"B","options":["afraid","interested","early","late"],"explanation":"be interested in 对……感兴趣。"},{"q":"3","answer":"C","options":["sell","lose","tell","buy"],"explanation":"tell that 看出。"},{"q":"4","answer":"D","options":["sold","lost","thrown","asked"],"explanation":"be asked to 被要求。"},{"q":"5","answer":"A","options":["agree","refuse","sleep","leave"],"explanation":"could only agree 只能同意。"},{"q":"6","answer":"B","options":["price","composition","noise","shop"],"explanation":"a simple composition 一首简单的作品。"},{"q":"7","answer":"C","options":["sold","hid","practised","broke"],"explanation":"practised the piece 练习曲子。"},{"q":"8","answer":"D","options":["in","off","out","up"],"explanation":"give up 放弃。"},{"q":"9","answer":"A","options":["perfectly","badly","slowly","sadly"],"explanation":"played perfectly 演奏得很完美。"},{"q":"10","answer":"B","options":["forget","enjoy","waste","lose"],"explanation":"enjoy it more 更加享受。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'Planning a Music Festival', 'Our school has decided to hold a music (1)____ on the sports field next month. The main (2)____ of the event is to raise money for charity. Students who can sing or play an instrument may (3)____ out as performers on the stage. Those who think they have no musical (4)____ can still help in many ways. Some will sell (5)____ at the gate, while others run food stands or set up the (6)____ before the show begins. In (7)____ to performing, my friend John will play the violin, and I have (8)____ to help with the crowds. We all hope the festival will (9)____ to be a great success. If it is for a good cause, everyone should take (10)____.', 121, 2, '[{"q":"1","answer":"C","options":["machine","garden","festival","market"],"explanation":"a music festival 音乐节。"},{"q":"2","answer":"D","options":["price","noise","weather","aim"],"explanation":"the main aim 主要目的。"},{"q":"3","answer":"A","options":["try","sell","hide","lose"],"explanation":"try out (for) 参加选拔/试演。"},{"q":"4","answer":"B","options":["price","talent","shop","city"],"explanation":"musical talent 音乐天赋。"},{"q":"5","answer":"C","options":["songs","rivers","tickets","trees"],"explanation":"sell tickets 卖票。"},{"q":"6","answer":"D","options":["weather","price","noise","equipment"],"explanation":"set up the equipment 架设设备。"},{"q":"7","answer":"A","options":["addition","price","noise","weather"],"explanation":"in addition to 除……之外。"},{"q":"8","answer":"B","options":["forgotten","offered","lost","sold"],"explanation":"offered to help 主动提出帮忙。"},{"q":"9","answer":"C","options":["break","leave","prove","lose"],"explanation":"prove to be 结果是。"},{"q":"10","answer":"D","options":["price","noise","rest","part"],"explanation":"take part 参与。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'The Father of the Virtual Choir', 'Eric Whitacre is an award-winning (1)____ and conductor. Born in the USA in 1970, he began (2)____ music at university in 1988. He fell in (3)____ with classical music while singing in the university choir. Over the next ten years, his (4)____ compositions became quite popular among singers. In 2009, he received a (5)____ of a girl singing one of his works. (6)____, he asked his fans to make their own videos, which he then (7)____ together into one performance. His first virtual choir had singers from twelve different (8)____ and received millions of views online. Since then, the virtual choir has become a worldwide (9)____. It is a wonderful way for people around the world to sing with one voice and (10)____ make the world a better place.', 129, 2, '[{"q":"1","answer":"A","options":["composer","farmer","driver","doctor"],"explanation":"an award-winning composer 获奖作曲家。"},{"q":"2","answer":"B","options":["selling","studying","hiding","losing"],"explanation":"studying music 学习音乐。"},{"q":"3","answer":"C","options":["hope","fear","love","rain"],"explanation":"fall in love with 爱上。"},{"q":"4","answer":"D","options":["empty","broken","silent","original"],"explanation":"original compositions 原创作品。"},{"q":"5","answer":"A","options":["video","price","noise","garden"],"explanation":"received a video 收到一段视频。"},{"q":"6","answer":"B","options":["Inspiring","Inspired","Inspire","Inspires"],"explanation":"Inspired 过去分词作状语,主语受到启发(被动)。"},{"q":"7","answer":"C","options":["sold","lost","joined","broke"],"explanation":"joined together 拼合在一起。"},{"q":"8","answer":"D","options":["prices","noises","shops","countries"],"explanation":"different countries 不同国家。"},{"q":"9","answer":"A","options":["phenomenon","machine","garden","market"],"explanation":"a worldwide phenomenon 全球现象。"},{"q":"10","answer":"B","options":["never","thus","hardly","seldom"],"explanation":"thus make 从而使。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'The Power of Hip-Hop', 'Leo grew up in an (1)____ neighbourhood where few people expected much of him. The first time he heard (2)____ music, something inside him woke up. The strong beat made him want to (3)____, and he taught himself the moves by watching videos. At first his friends (4)____ at him, but Leo did not give up. Practising for hours every day, he slowly turned into a real (5)____. Music gave his ordinary days new (6)____, and dancing brought him a sense of (7)____. Later he joined a small (8)____ of dancers, and together they performed on a street (9)____ for crowds of strangers. (10)____ tired or nervous, Leo always felt free the moment the music began.', 116, 2, '[{"q":"1","answer":"C","options":["golden","royal","ordinary","silent"],"explanation":"an ordinary neighbourhood 普通街区。"},{"q":"2","answer":"D","options":["classical","country","folk","hip-hop"],"explanation":"hip-hop music 嘻哈音乐(下文 beat / dance 呼应)。"},{"q":"3","answer":"A","options":["dance","sleep","cry","leave"],"explanation":"want to dance 想跳舞。"},{"q":"4","answer":"B","options":["smiled","laughed","looked","pointed"],"explanation":"laughed at him 嘲笑他。"},{"q":"5","answer":"C","options":["farmer","driver","performer","doctor"],"explanation":"a real performer 真正的表演者。"},{"q":"6","answer":"D","options":["price","noise","weather","energy"],"explanation":"new energy 新的活力。"},{"q":"7","answer":"A","options":["satisfaction","price","noise","weather"],"explanation":"a sense of satisfaction 满足感。"},{"q":"8","answer":"B","options":["price","band","shop","city"],"explanation":"a band of dancers 一群舞者。"},{"q":"9","answer":"C","options":["river","tree","stage","cloud"],"explanation":"a street stage 街头舞台。"},{"q":"10","answer":"D","options":["Because","Unless","Until","Though"],"explanation":"Though tired or nervous 尽管又累又紧张(让步)。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'The Composer Who Could Not Hear', 'Ludwig van Beethoven is one of the greatest (1)____ in history. Born in Germany, he started his musical training when he was very (2)____. He soon became famous as a pianist, and by 1800 many people (3)____ him the most important composer of his time. During the same period, however, he slowly began to lose his (4)____. Even though he could not hear with his ears, he could still (5)____ music in his head. Most of his greatest (6)____ were completed after he became deaf. In later life he faced many health and money (7)____, and he often felt lonely. His friends tried to (8)____ him through his dark times. (9)____ by sadness as his life was, he never stopped creating beautiful music. Today his works still (10)____ the hearts of listeners all over the world.', 136, 2, '[{"q":"1","answer":"A","options":["composers","farmers","drivers","doctors"],"explanation":"the greatest composers 最伟大的作曲家。"},{"q":"2","answer":"B","options":["old","young","tall","rich"],"explanation":"very young 很小的时候。"},{"q":"3","answer":"C","options":["sold","lost","thought","broke"],"explanation":"thought him… 认为他是……。"},{"q":"4","answer":"D","options":["money","garden","ticket","hearing"],"explanation":"lose his hearing 失去听力。"},{"q":"5","answer":"A","options":["hear","sell","hide","throw"],"explanation":"hear music in his head 在脑中听到音乐。"},{"q":"6","answer":"B","options":["prices","works","noises","shops"],"explanation":"greatest works 最伟大的作品。"},{"q":"7","answer":"C","options":["songs","gardens","issues","markets"],"explanation":"health and money issues 健康和金钱问题。"},{"q":"8","answer":"D","options":["sell","lose","break","help"],"explanation":"help him through 帮他度过。"},{"q":"9","answer":"A","options":["Marked","Marking","Mark","Marks"],"explanation":"Marked by sadness 被悲伤笼罩(过去分词作让步状语,被动)。"},{"q":"10","answer":"B","options":["leave","touch","sell","lose"],"explanation":"touch the hearts 打动人心。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U5', 'Our First Album', 'Last year my friends and I formed a small (1)____ and dreamed of making our own album. None of us was a professional (2)____, so the songs were far from perfect at first. We could not (3)____ a real recording studio, so we set up cheap (4)____ in my garage instead. Night after night we (5)____ the same songs until they sounded right. (6)____ enough time and practice, even ordinary players can create something good. When the album was finally (7)____, we shared it online, and to our (8)____ many strangers liked it. Their warm (9)____ gave us the courage to keep going. (10)____ in a tiny garage, that first album still means more to us than any prize.', 119, 2, '[{"q":"1","answer":"C","options":["price","garden","band","market"],"explanation":"formed a small band 组建小乐队。"},{"q":"2","answer":"D","options":["farmer","driver","doctor","musician"],"explanation":"a professional musician 专业音乐人。"},{"q":"3","answer":"A","options":["afford","sell","lose","break"],"explanation":"could not afford 负担不起。"},{"q":"4","answer":"B","options":["weather","equipment","noise","price"],"explanation":"cheap equipment 便宜的设备。"},{"q":"5","answer":"C","options":["sold","lost","recorded","hid"],"explanation":"recorded the same songs 录同样的歌。"},{"q":"6","answer":"D","options":["Giving","Give","Gives","Given"],"explanation":"Given enough time 倘若有足够时间(过去分词作条件状语,被动)。"},{"q":"7","answer":"A","options":["ready","sold","lost","broken"],"explanation":"was finally ready 终于做好了。"},{"q":"8","answer":"B","options":["price","surprise","noise","weather"],"explanation":"to our surprise 令我们惊讶的是。"},{"q":"9","answer":"C","options":["price","noise","reaction","weather"],"explanation":"warm reaction 热烈的回应。"},{"q":"10","answer":"D","options":["Recording","Record","Records","Recorded"],"explanation":"Recorded in a tiny garage 在小车库里录制(过去分词作状语,被动)。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Music Preferences', '必修二 U5 · dialogue', 3, 'Anna: What kind of music do you like, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 The School Music Festival', '必修二 U5 · passage', 2, 'Good morning, everyone. Our school music festival will be held next month on the sports field.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Learning the Guitar', '必修二 U5 · dialogue', 3, 'Ben: I''m really struggling with the guitar. My fingers just won''t move fast enough.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 What a Virtual Choir Is', '必修二 U5 · passage', 2, 'A virtual choir lets people sing together even when they are far apart.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Choosing an Instrument', '必修二 U5 · dialogue', 3, 'Lucy: I''d like to learn an instrument, but I can''t decide which one.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 Music and Your Mood', '必修二 U5 · passage', 2, 'Here is a simple idea for anyone who feels tired or sad.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Speech about How Music Has Helped You(写一篇关于音乐如何帮助你的演讲)', 'How Music Changed My Life', '假设你叫李华,要在校园音乐分享会上做一个约100词的英语演讲。请讲述音乐对你(或你认识的人)的影响,内容包括:① 自我介绍并点明演讲主题;② 描述你与音乐的一段经历(如哪种音乐/哪支乐队帮过你);③ 说明音乐如何改变了你的心情或生活;④ 鼓励同学也让音乐成为生活的一部分。注意:适当用一两种修辞(比喻/引用/反问)。', 'Suppose you are Li Hua. Give a short speech (about 100 words) at a school music event about how music has helped you or someone you know. Include: 1) introduce yourself and your topic; 2) describe an experience with music (a kind of music or a band that helped you); 3) explain how music changed your mood or life; 4) encourage classmates to make music part of their lives. Use one or two rhetorical devices (a metaphor, a quote, or a rhetorical question).', '["自我介绍 + 点题(It''s an honour to share how music has changed my life.)","音乐经历(Two years ago, when I felt low, I found a band / a kind of music …)","音乐的作用(Music gave me strength and brought me relief.)","鼓励 + 修辞(Have you ever …? / Music is the medicine of the mind.)"]'::jsonb, 70, 100, 'Good morning, everyone! My name is Li Hua, and it is an honour to share how music has changed my life. Have you ever faced a time when everything looked dark? Last year, before my exams, I felt tired and alone. Then I discovered a band whose gentle songs became the rock I leant on. When I listened, music gave me strength and brought me relief; somehow it lifted my spirits like a kite in the wind. As one writer said, "Music is the medicine of the mind." So whatever you are feeling, please make music a part of your life. Thank you!', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["It is an honour to share how music has changed my life.","Music gave me strength and brought me relief.","Moved by its gentle songs, I slowly found hope again.","Whatever you are feeling, the right music can make it better."]'::jsonb, '[{"wrong":"Move by the song, I felt better.","correct":"Moved by the song, I felt better.","note":"主语 I 被歌曲打动(被动),状语用过去分词 Moved,不用原形 Move。"},{"wrong":"Music give me strength.","correct":"Music gives me strength.","note":"主语 Music 第三人称单数,动词加 s。"},{"wrong":"I''d like to share how music changed my life with you all happily.","correct":"I''d like to share with you all how music changed my life.","note":"share with sb sth 语序;避免状语堆在句末造成歧义。"}]'::jsonb, '【音乐演讲结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required2', 'U5', '{"title":"过去分词作状语 速查","intro":"过去分词(done)放在句首或句中作状语,可表时间、原因、条件、让步。判断口诀:看分词的逻辑主语——它一定是主句主语;主语承受动作(被动/完成)用过去分词 done,主语发出动作(主动/进行)用现在分词 doing。","table":{"headers":["状语意义","例句 / 等价从句"],"rows":[["时间/原因","Moved by his words, she accepted his gift.(= Because she was moved…)"],["条件","Given more time, we could finish.(= If we were given more time…)"],["让步","Though invited, he didn''t come.(= Though he was invited…)"],["被动 vs 主动","Used for shows, the hall is full of energy.(被动)≠ Using…(主动)"]]},"specialRules":[{"rule":"过去分词的逻辑主语 = 主句主语,且二者是被动/完成关系","mark":"Painted in dark colours, the room needed lights.(room 被刷漆)"},{"rule":"主语发出动作(主动)→ 必须改用现在分词 doing","mark":"Recording at home, the members joined the videos.(members 主动录)"},{"rule":"表条件常用 Given …;表让步常保留 though/although + done","mark":"Given a chance √ / Though invited √"},{"rule":"be born / be filled with / be interested in 等被动短语,作状语只留分词","mark":"Born in 1970, he… / Filled with spirit, they…"}],"why":["状语从句与主句主语相同、且从句是被动语态时,可省去从句主语和 be 动词,只留过去分词;过去分词本身就带''被动/完成''之意,所以无须再写 was/were。"],"gaokaoPoints":["done 还是 doing:抓住''主句主语是动作的承受者还是发出者''——承受者用 done,发出者用 doing。语法填空、读后续写高频。","Given / Moved / Born / Faced with 等开头的状语结构是写作高分句式;条件用 Given,让步用 Though + done。"],"examVsReal":[{"exam":"Moved by the song, she cried.(考试/书面)","real":"The song moved her so much that she cried.","note":"考试爱考分词状语的紧凑句式;口语里更常用 so … that 或直接两句话。"},{"exam":"Given more time, we could finish.(考试)","real":"If we had more time, we could finish.","note":"考试用 Given 体现凝练;日常表达常还原成 if 从句,更口语化。"}]}'::jsonb);
